import { AlertTriangle, LockKeyhole } from "lucide-react";
export default function SetupRequiredPage(){return <div className="panel" style={{maxWidth:600,margin:"8vh auto"}}><div className="panel-header"><div><div className="panel-title">Private deployment is not configured</div><div className="panel-subtitle">The application has failed closed to protect source-derived Toyota project information.</div></div><LockKeyhole size={18}/></div><div className="panel-body"><div className="callout callout-danger"><AlertTriangle size={16}/>Production deployments must configure Supabase authentication before any project page or reference data is exposed.</div><ol className="result-list"><li>Set NEXT_PUBLIC_SUPABASE_URL.</li><li>Set NEXT_PUBLIC_SUPABASE_PUBLISHABLE_KEY.</li><li>Apply the Supabase migrations.</li><li>Create an administrator account and assign the admin role.</li><li>Restart or redeploy the application.</li></ol></div></div>}
